<template><div class="ui-table-scroll"><Table :data="rows" :columns="columns" no-data-text="暂无SKU资料" :min-width="snapshot?1050:900"><template slot="spec" slot-scope="{row}">{{skuSpecs(row.specifications)}}<p class="ui-meta">{{row.code||'编码未提供'}}</p></template><template slot="price" slot-scope="{row}">{{money(row.priceCent)}}</template><template slot="weight" slot-scope="{row}">{{row.weightGram==null?'未填写':decimal(row.weightGram,3)+' 千克'}}</template><template slot="stock" slot-scope="{row}">{{liveFor(row).quantity==null?'未填写':liveFor(row).quantity}}<p class="ui-meta">库存 v{{liveFor(row).inventoryVersion==null?'未提供':liveFor(row).inventoryVersion}}</p></template><template slot="held" slot-scope="{row}">{{liveFor(row).heldQuantity==null?'未核实':liveFor(row).heldQuantity}}</template><template slot="snapshotStock" slot-scope="{row}">{{row.quantity==null?'未提供':row.quantity}}</template><template slot="cost" slot-scope="{row}">{{money(liveFor(row).costCent)}}<p class="ui-meta">成本 v{{liveFor(row).costVersion==null?'未提供':liveFor(row).costVersion}}</p></template><template slot="state" slot-scope="{row}">{{row.enabled?'启用':'停用'}}</template><template slot="id" slot-scope="{row}"><span class="ui-meta">{{row.id}}</span></template></Table><p class="ui-note">{{snapshot?'送审售价／规格／重量来自当前所选送审快照；当前库存与成本独立读取，不由审核动作回写。':'当前库存、成本和内容版本独立；平台此处只读。'}}</p></div></template>
<script>import {money,decimal,skuSpecs} from '../display.cjs';export default {props:{rows:{type:Array,default:()=>[]},live:{type:Array,default:()=>[]},snapshot:Boolean,held:Boolean},computed:{costVisible(){return this.live.some(r=>Object.prototype.hasOwnProperty.call(r,'costCent'))||this.rows.some(r=>Object.prototype.hasOwnProperty.call(r,'costCent'));},columns(){return [{title:'规格／编码',slot:'spec',minWidth:190},{title:'售价',slot:'price',minWidth:115},{title:'重量',slot:'weight',minWidth:125},...(this.snapshot?[{title:'送审库存',slot:'snapshotStock',minWidth:110}]:[]),{title:'当前可售库存',slot:'stock',minWidth:145},...(this.held?[{title:'当前占用 H',slot:'held',minWidth:110}]:[]),...(this.costVisible?[{title:'当前成本（已授权）',slot:'cost',minWidth:160}]:[]),{title:'SKU状态',slot:'state',width:100},{title:'稳定SKU编号',slot:'id',minWidth:190}];}},methods:{money,decimal,skuSpecs,liveFor(row){return this.live.find(r=>r.id===row.id)||row;}}};</script>
